		const words = { ...(lang.slice(0, 2) === "da" ? DA : EN) };
		if (isObj(raw.words)) for (const k of Object.keys(EN)) if (typeof raw.words[k] === "string" && raw.words[k].trim()) words[k] = cut(raw.words[k], MAX.word);
